28			if (text.length <= maxLength) {
29				return text;
30			}
31	
32			const halfLength = Math.floor((maxLength - 1) / 2);
33			const start = text.substring(0, halfLength);
34			const end = text.substring(text.length - halfLength);
35	
36			return `${start}…${end}`;
37		}
